import assert from 'node:assert/strict';
import { visible } from './consumer-a.mjs';
import { allowed } from './consumer-b.mjs';
for (const [fn, min, max] of [[visible, 0, 10], [allowed, -5, 5]]) {
  for (const value of [min - 1, min, max, max + 1]) assert.equal(fn(value), value >= min && value <= max);
}

import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
assert.equal(JSON.parse(readFileSync(new URL('./pricing.json', import.meta.url))).rate, 7);
assert.deepEqual(JSON.parse(readFileSync(new URL('./logging.json', import.meta.url))), { level: 'info' });
assert.deepEqual(JSON.parse(readFileSync(new URL('./storage.json', import.meta.url))), { version: 1 });

import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
const evidence = JSON.parse(readFileSync(new URL('./evidence/manifest.json', import.meta.url)));
assert.ok(Array.isArray(evidence.sources) && evidence.sources.length > 0);
for (const source of evidence.sources) {
  assert.equal(typeof source.locator, 'string');
  assert.match(source.hash, /^[a-f0-9]{64}$/);
}
assert.equal(evidence.initial_failure, 'F-01');

